app.json:
{
  "agent": {
    "name": "Roadmap assistant",
    "file": "agent.md"
  },
  "budget": {
    "per_run": 0.10
  },
  "capabilities": {
    "records": {
      "feedback": "rw",
      "theme": "rw",
      "issue": "rw",
      "draft": "rw"
    },
    "connectors": {
      "gmail": {
        "can": [
          "send"
        ],
        "approve": [
          "send"
        ]
      },
      "slack": {
        "can": [
          "post"
        ],
        "approve": [
          "post"
        ]
      }
    },
    "ai": [
      "summarise",
      "sort"
    ]
  },
  "commands": [
    {
      "id": "draft-prd",
      "label": "Draft PRD",
      "for": "theme",
      "run": "draft-prd",
      "params": {
        "theme": "$record.id"
      }
    },
    {
      "id": "draft-release-notes",
      "label": "Draft release notes",
      "for": "theme",
      "run": "draft-release-notes",
      "params": {
        "theme": "$record.id"
      }
    },
    {
      "id": "comment-issue",
      "label": "Draft Linear comment",
      "for": "issue",
      "run": "comment-issue",
      "params": {
        "issue": "$record.id"
      }
    }
  ],
  "id": "01M8DDCAS7NRZ863AZDEXTXCHB",
  "kit": 2,
  "name": "Feedback to Roadmap",
  "records": {
    "draft": {
      "title": "title",
      "fields": {
        "title": {
          "type": "text",
          "required": true
        },
        "kind": {
          "type": "enum",
          "values": [
            "PRD",
            "Release note"
          ],
          "required": true,
          "default": "PRD"
        },
        "body": {
          "type": "text"
        },
        "theme": {
          "type": "ref",
          "to": "theme"
        }
      }
    },
    "feedback": {
      "title": "text",
      "fields": {
        "text": {
          "type": "text",
          "required": true
        },
        "source": {
          "type": "enum",
          "values": [
            "Slack",
            "Support",
            "Transcript"
          ],
          "required": true,
          "default": "Slack"
        },
        "author": {
          "type": "text"
        },
        "captured_at": {
          "type": "date"
        },
        "url": {
          "type": "text"
        },
        "theme": {
          "type": "ref",
          "to": "theme"
        }
      }
    },
    "issue": {
      "title": "title",
      "fields": {
        "identifier": {
          "type": "text",
          "required": true,
          "unique": true
        },
        "title": {
          "type": "text",
          "required": true
        },
        "url": {
          "type": "text"
        },
        "status": {
          "type": "enum",
          "values": [
            "Open",
            "In progress",
            "Done"
          ]
        },
        "theme": {
          "type": "ref",
          "to": "theme"
        }
      }
    },
    "theme": {
      "title": "name",
      "fields": {
        "name": {
          "type": "text",
          "required": true,
          "unique": true
        },
        "summary": {
          "type": "text"
        },
        "mentions": {
          "type": "number"
        },
        "status": {
          "type": "enum",
          "values": [
            "New",
            "Exploring",
            "Planned",
            "Shipped"
          ],
          "required": true,
          "default": "New"
        }
      }
    }
  },
  "triggers": [
    {
      "id": "new-quote",
      "on": "record.changed",
      "type": "feedback",
      "run": "ingest-quotes"
    },
    {
      "id": "weekly-digest",
      "on": "schedule",
      "cron": "0 8 * * 1",
      "run": "weekly-digest"
    }
  ],
  "version": 1
}
